// TestGolden_Pipeline locks the end-to-end pipeline output (see file header).
func TestGolden_Pipeline(t *testing.T) {
	loc, err := time.LoadLocation("Europe/Dublin")
	if err != nil {
		t.Fatalf("load Europe/Dublin: %v", err)
	}

	// Build the full pipeline exactly as production does.
	db := loadFixtureDB(t)
	poller := NewPoller("", "", NewDB(db))
	withClock(poller.Store(), fixtureNow()) // deterministic LiveStore clock
	if err := poller.parse(loadFixtureFeed(t)); err != nil {
		t.Fatalf("parse realtime fixture: %v", err)
	}

	now := fixtureNow()
	for _, stop := range fixtureStops() {
		want := goldenWant[stop]
		got := QueryArrivals(db, poller.Store(), stop, now, 90, 0, nil)

		if len(got) != len(want) {
			t.Errorf("stop %s: got %d arrivals, want %d", stop, len(got), len(want))
			// Dump the actual rows to make re-baselining easy on a real change.
			for i, a := range got {
				t.Logf("  got[%d] = {RouteShort: %q, Headsign: %q, Scheduled: %q, HasRealtime: %v, DelayMinutes: %d, IsAdded: %v}",
					i, a.RouteShort, a.Headsign, a.ScheduledTime.In(loc).Format("15:04"),
					!a.RealtimeTime.IsZero(), a.DelayMinutes, a.IsAdded)
			}
			continue
		}

		for i, a := range got {
			g := goldenArrival{
				RouteShort:   a.RouteShort,
				Headsign:     a.Headsign,
				Scheduled:    a.ScheduledTime.In(loc).Format("15:04"),
				HasRealtime:  !a.RealtimeTime.IsZero(),
				DelayMinutes: a.DelayMinutes,
				IsAdded:      a.IsAdded,
			}
			if g != want[i] {
				t.Errorf("stop %s arrival[%d]:\n  got  %+v\n  want %+v", stop, i, g, want[i])
			}
		}
	}
}
